direct_query.sparql:
SELECT DISTINCT ?publication ?title
WHERE {
  ?publication a <https://catalog.example.org/ns/Publication> ;
               <https://catalog.example.org/ns/fundedBy> ?grant ;
               <https://catalog.example.org/ns/title> ?title .
  ?grant <https://catalog.example.org/ns/grantNumber> "NORD-42" .
}

SELECT DISTINCT ?project ?projectTitle WHERE {
  ?employee a <https://example.org/staffing/Employee> ;
            <https://example.org/staffing/displayName> "Alice Nguyen" ;
            <https://example.org/staffing/workedOn> ?project .
  ?project a <https://example.org/staffing/Project> ;
           <https://example.org/staffing/title> ?projectTitle .
}

PREFIX staff: <https://example.org/staffing/>
SELECT DISTINCT ?employeeName
WHERE {
  ?employee a staff:Employee ;
            staff:displayName ?employeeName ;
            staff:workedOn ?project ;
            staff:expertise ?skill .
  ?project a staff:Project ;
           staff:title "Project Atlas" .
  ?skill a staff:Skill ;
         staff:label "artificial intelligence" .
}

PREFIX ops: <https://example.test/ops/>
SELECT ?service WHERE {
  ?service a ops:Service ;
           ops:ownedBy ?team .
  ?team a ops:Team .
  FILTER(CONTAINS(LCASE(STR(?team)), "commerce"))
  ?service ops:hasDeployment ?deployment .
  ?deployment a ops:Deployment ;
              ops:environment "production" .
}

PREFIX staffing: <https://example.org/staffing/>
SELECT (EXISTS {
  ?employee a staffing:Employee ;
            staffing:displayName "Priya" ;
            staffing:workedOn ?project .
  ?project a staffing:Project ;
           staffing:title "Atlas" .
} AS ?staffed) WHERE {}

SELECT DISTINCT ?researcherName WHERE {
  ?publication a <https://catalog.example.org/ns/Publication> ;
               <https://catalog.example.org/ns/publishedIn> ?venue ;
               <https://catalog.example.org/ns/contributor> ?researcher .
  ?venue <https://catalog.example.org/ns/displayName> "Journal A" .
  ?researcher a <https://catalog.example.org/ns/Researcher> ;
              <https://catalog.example.org/ns/displayName> ?researcherName .
}

PREFIX ex: <https://example.org/staffing/>
SELECT ?employeeName (COUNT(DISTINCT ?project) AS ?projectCount)
WHERE {
  ?employee a ex:Employee ;
            ex:displayName ?employeeName ;
            ex:workedOn ?atlasProject ;
            ex:workedOn ?project .
  ?atlasProject ex:title "Project Atlas" .
}
GROUP BY ?employeeName
ORDER BY ?employeeName

